const activity={1:{start:'ch1-change',readiness:'ch1-change',case:'ch1-allocation',lab:'ch1-comparison',finish:'ch1-allocation'},2:{start:'ch2-return',returns:'ch2-return',compound:'ch2-growth',discount:'ch2-discount',inflation:'ch2-inflation',lab:'ch2-transfer',finish:'ch2-transfer'}};
export function pythonLink(chapter,step){const id=activity[chapter]?.[step];if(!id)return '';const prefix=chapter===1?'python/':'../python/';return `<section class="callout" aria-label="選做 Python 鞏固練習"><strong>用 Python 鞏固這個概念</strong><p>先看範例，編輯小型程式，執行真正的 Python，再用不同輸入檢查方法。 <a href="${prefix}?chapter=${chapter}#${id}">試試對應的 Python 活動</a></p><p class="mini">額外選做練習：約 ${chapter===1?'40':'65'} 分鐘，對應章節 ${chapter}, 另加首次設定時間。程式練習與核心課程進度分開儲存。</p></section>`;}
